        {"id": "lesson_03_q4", "type": "multiple_choice", "prompt": "A sentence STARTS with a question word ('Which one is a car?'). Which particle marks the question word?", "choices": ["wa", "ga", "ka", "no"], "answerIndex": 1, "explanation": "When a question word is the topic or first word, ga must be used instead of wa.", "source": "lesson_03 p.72", "verified": True, "skill": "grammar"},
